// 1. Obtener el path original desde el body
let originalPath = $json.body?.path || "";

// 2. Si el path no está vacío, procesarlo
if (originalPath) {
  // Remover corchetes iniciales/finales, comillas y limpiar espacios
  originalPath = originalPath.trim();

  if (originalPath.startsWith('[') && originalPath.endsWith(']')) {
    originalPath = originalPath.slice(1, -1);
  }

  // Limpieza final por seguridad (quita espacios residuales o comillas sueltas)
  originalPath = originalPath.replace(/['"]/g, '').trim();
}

// 3. Devolver el objeto modificado agregando la variable limpia
return {
  ...$json,
  body: {
    ...$json.body,
    path: originalPath
  }
};
